<template><div class="app-container"><el-table v-loading="loading" :data="list"><el-table-column prop="userId" label="用户ID" width="80" /><el-table-column prop="userName" label="用户名" /><el-table-column prop="nickName" label="昵称" /><el-table-column prop="deptName" label="部门" /><el-table-column prop="phonenumber" label="手机号" /><el-table-column label="操作" width="150"><template #default="scope"><el-button link type="primary" icon="Edit">编辑</el-button><el-button link type="primary" icon="Delete">删除</el-button></template></el-table-column></el-table><pagination v-show="total>0" :total="total" v-model:page="queryParams.pageNum" v-model:limit="queryParams.pageSize" @pagination="getList" /></div></template>
<script setup lang="ts">import { ref, reactive, onMounted } from 'vue';import request from '@/utils/request';const loading=ref(false), total=ref(0), list=ref<any[]>([]);const queryParams=reactive({pageNum:1,pageSize:10});const getList=async()=>{loading.value=true;try{const res=await request({url:'/system/user/list',method:'get',params:queryParams});list.value=res.rows;total.value=res.total}finally{loading.value=false}};onMounted(getList)</script>
